import {actualParts} from '../prototype/actual-parts.js';
import {initializeSources,sourceFor,snapshotOptions} from './addon-model.mjs';
import {createWebErp} from './erp-ui.mjs';
import {createBatchUI} from './batch-ui.mjs';
import {createAddonUI} from './addon-ui.mjs';
