const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const cloud=globalThis.webLiteCloud;
const storageKey=cloud?.key||STORAGE_KEY;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v===null?'—':(v<0?'-':'')+'¥'+Math.abs(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const time=v=>new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',shop:'<path d="M3 10V7l2-4h14l2 4v3M4 11v10h16V11M9 21v-7h6v7M3 7h18M3 10c0 4 5 4 5 0 0 4 8 4 8 0 0 4 5 4 5 0"/>',folder:'<path d="M3 6a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',link:'<path d="m10 13 4-4m-6 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0" transform="translate(2 -1)"/>',doc:'<path d="M5 3h9l5 5v13H5Z M14 3v6h5 M8 13h8M8 17h6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',sync:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',cloud:'<path d="M7 18H5a4 4 0 0 1-1-8 7 7 0 0 1 13-3 5 5 0 0 1 2 11h-2M12 21V11m-4 4 4-4 4 4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',calc:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8M8 11h1m5 0h2m-8 4h1m5 0h2m-8 4h1m5 0h2"/>',plus:'<path d="M12 4v16M4 12h16"/>',arrow:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',x:'<path d="m6 6 12 12M18 6 6 18"/>',undo:'<path d="M4 11h11a6 6 0 0 1 0 12M4 11l6-6M4 11l6 6" transform="translate(0 -3)"/>',save:'<path d="M4 3h13l3 3v15H4ZM8 3v6h8V3M8 21v-8h8v8"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.doc}</svg>`;
const button=(text,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
let state,knownRevision=0,locked=false,corruptRaw=false,sourceMigration=false,storageError='',rawStorage='',toastTimer,modalSubmit=null;
let ui={view:'overview',scope:{type:'product',id:'p1'},shopId:'intel',productId:'p1',active:'c2',query:'',treeQuery:'',profit:'all',sort:'default',closed:new Set(['shop:gigabyte','shop:jonsbo','product:p2','product:p3','product:p4','product:p5','templates:intel','templates:gigabyte','templates:jonsbo']),mobileTree:false};
try{rawStorage=cloud?'cloud':localStorage.getItem(storageKey)||'';state=cloud?copy(cloud.initial):rawStorage?JSON.parse(rawStorage):createDemo();if(state.schemaVersion!==1||!['shops','products','configs','catalog','templates','logs'].every(k=>Array.isArray(state[k]))||!state.drafts)throw Error('原型缓存格式不兼容');knownRevision=state.revision||0;sourceMigration=initializeSources(state);}catch(e){locked=true;corruptRaw=true;storageError='无法读取原型缓存，原数据未覆盖。请先导出缓存后再检查浏览器存储。';state=createDemo();initializeSources(state);}
const shop=()=>state.shops.find(s=>s.id===ui.shopId)||state.shops[0];
const product=()=>state.products.find(p=>p.id===ui.productId);
const current=()=>state.drafts[ui.active]||state.configs.find(c=>c.id===ui.active);
const configShop=c=>state.shops.find(s=>s.id===state.products.find(p=>p.id===c.productId)?.shopId)||shop();
let catalogIndex,productIndex,configGroups,statsCache=new WeakMap(),overviewPage=0,overviewKey='',treePages=new Map();
function indexView(){state.configs=restoreConfigOrder(state.configs);state.templates=state.templates.map(t=>({...t,configs:restoreConfigOrder(t.configs)}));catalogIndex=new Map(state.catalog.map(p=>[p.goodsId,p]));productIndex=new Map(state.products.map(p=>[p.id,p]));configGroups=new Map();for(const c of state.configs){const list=configGroups.get(c.productId)||[];list.push(c);configGroups.set(c.productId,list);}statsCache=new WeakMap();}
const stats=c=>{if(!statsCache.has(c))statsCache.set(c,calculate(c,catalogIndex,configShop(c).coupon));return statsCache.get(c);};
function syncToastLayer(){const el=$('#toast');if(typeof el.showPopover==='function'){el.setAttribute('popover','manual');if(el.matches(':popover-open'))el.hidePopover();if(el.classList.contains('visible'))el.showPopover();}else if($('#modal').open&&el.classList.contains('visible')){const status=$('#modal-status');if(status){status.textContent=el.textContent;status.classList.add('toast-fallback');}}}
function toast(text){clearTimeout(toastTimer);const el=$('#toast');el.textContent=text;el.classList.add('visible');syncToastLayer();toastTimer=setTimeout(()=>{el.classList.remove('visible');if(typeof el.hidePopover==='function'&&el.matches(':popover-open'))el.hidePopover();},6000);}
function persist(draftOnly=false){
 if(locked)throw Error(storageError||'另一窗口已修改数据，请导出当前副本后刷新');
 if(cloud){if(draftOnly&&cloud.writeDrafts){const result=cloud.writeDrafts(state);knownRevision=state.revision;return result;}cloud.prepare(state);const result=cloud.write(state);knownRevision=state.revision;cloud.accepted(state);return result;}
 const stored=JSON.parse(localStorage.getItem(storageKey)||'null');if(stored&&stored.revision!==knownRevision){locked=true;storageError='另一窗口已保存修改。请导出当前副本，再刷新读取最新数据。';throw Error(storageError);}
 cloud?.prepare(state);
 const next=knownRevision+1;localStorage.setItem(storageKey,JSON.stringify({...state,revision:next}));state.revision=knownRevision=next;cloud?.accepted(state);storageError='';
}
function commit(message,fn){const before=copy(state);try{fn();state.logs.unshift({id:uid(),at:new Date().toISOString(),message});state.logs=state.logs.slice(0,150);persist();}catch(e){state=before;throw e;}}
async function run(fn){try{await fn();if(cloud)await cloud.flush();}catch(e){toast(e.message);const warning=$('#storage-error');if(warning){warning.textContent=storageError||'';warning.hidden=!storageError;}}}
function edit(mutator){statsCache=new WeakMap();if(cloud?.busy)throw Error('同步进行中，请稍后编辑');if(locked)throw Error(storageError);const c=current();if(!c)return;state.drafts[c.id]??=copy(c);mutator(state.drafts[c.id]);try{persist(true);}catch(e){storageError=e.message;toast('草稿未能保存到浏览器：'+e.message);}updatePricing();}
async function saveCurrent(back=false){const c=current();validateConfig(c);commit('保存配置：'+c.name,()=>{const i=state.configs.findIndex(x=>x.id===c.id);state.configs[i]=copy(c);delete state.drafts[c.id];});if(cloud)await cloud.flush();if(back)ui.view='overview';render();toast('配置已保存到此浏览器');}
function download(value,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function visibleConfigs(){const scope=ui.scope;return state.configs.filter(c=>{const p=productIndex.get(c.productId);return p&&(scope.type==='product'?p.id===scope.id:scope.type==='category'?p.shopId===scope.id&&p.category===scope.category:p.shopId===scope.id);});}
function scopeTitle(){return ui.scope.type==='product'?product()?.name:ui.scope.type==='category'?ui.scope.category:shop().name;}
function crumbs(){return `<span>${esc(shop().name)}</span>${product()&&ui.scope.type==='product'?`<b>/</b><span>${esc(product().category)}</span><b>/</b><span>${esc(product().name)}</span>`:ui.scope.type==='category'?`<b>/</b><span>${esc(ui.scope.category)}</span>`:''}`;}
function summaryMarkup(config){return `<span class="summary-name">${esc(config.name)}：</span><span class="summary-parts">${configurationSummary(config).map((p,i)=>`${i?'<span class="summary-plus"> + </span>':''}<span class="summary-part" title="${esc(p.slot+'：'+p.detail)}">${esc(p.text)}</span>`).join('')}</span>`;}
function summaryTitle(config){return config.name+'：'+configurationSummary(config).map(p=>p.text).join(' + ');}
function tree(){
 const query=ui.treeQuery.trim().toLowerCase(),open=key=>!!query||!ui.closed.has(key);
 const node=(label,key,action,id,kind,extra='')=>`<div class="tree-line"><button class="tree-toggle" data-action="toggle" data-id="${esc(key)}" aria-label="${ui.closed.has(key)?'展开':'收起'}${esc(label)}" aria-expanded="${open(key)}">${icon('arrow',open(key)?'down':'')}</button>${button(icon(kind)+`<span>${esc(label)}</span>${extra}`,action,'tree-label',`data-id="${esc(id)}"`)}</div>`;
 return state.shops.map(s=>{const matchShop=s.name.toLowerCase().includes(query),templates=state.templates.filter(t=>t.shopId===s.id),products=state.products.filter(p=>p.shopId===s.id),found=products.filter(p=>!query||matchShop||[p.name,p.category,...(configGroups.get(p.id)||[]).map(c=>summaryTitle(state.drafts[c.id]||c)+' '+c.version)].join(' ').toLowerCase().includes(query));if(query&&!found.length&&!templates.some(t=>t.name.toLowerCase().includes(query))&&!query.includes('模板'))return '';
 const contents=open('shop:'+s.id)?`<div class="tree-children">${[...new Set(found.map(p=>p.category))].map(category=>{const key='category:'+s.id+category;return node(category,key,'category',s.id+'|'+category,'folder')+(open(key)?`<div class="tree-children">${found.filter(p=>p.category===category).map(p=>{const all=configGroups.get(p.id)||[],matches=query&&!matchShop&&!p.name.toLowerCase().includes(query)&&!p.category.toLowerCase().includes(query)?all.filter(c=>(summaryTitle(state.drafts[c.id]||c)+' '+c.version).toLowerCase().includes(query)):all,page=treePages.get(p.id)||0;
 return node(p.name,'product:'+p.id,'product',p.id,'link',`<small>${all.length}</small>`)+(open('product:'+p.id)?`<div class="tree-configs">${matches.slice(page*60,page*60+60).map(c=>button(icon('doc')+`<span class="tree-config-copy"><span class="config-summary">${summaryMarkup(state.drafts[c.id]||c)}</span>${c.version?`<small class="config-version">${esc(c.version)}</small>`:''}</span>${state.drafts[c.id]?'<i class="draft-dot" title="未提交草稿"></i>':''}`,'edit','tree-config '+(ui.view==='editor'&&ui.active===c.id?'active':''),`data-id="${esc(c.id)}"`)).join('')}${matches.length>60?`<div class="tree-pages">${button('上一页','tree-prev','text-button',`data-id="${esc(p.id)}" ${page?'':'disabled'}`)}<small>${page+1}/${Math.ceil(matches.length/60)}</small>${button('下一页','tree-next','text-button',`data-id="${esc(p.id)}" ${(page+1)*60>=matches.length?'disabled':''}`)}</div>`:''}</div>`:'');}).join('')}</div>`:'');}).join('')}${node('配置模板','templates:'+s.id,'templates',s.id,'folder',`<small>${templates.length}</small>`)}${open('templates:'+s.id)?`<div class="tree-children">${templates.filter(t=>!query||matchShop||query.includes('模板')||t.name.toLowerCase().includes(query)).map(t=>button(icon('doc')+`<span>${esc(t.name)}</span>`,'template-detail','tree-config',`data-id="${esc(t.id)}"`)).join('')}</div>`:''}</div>`:'';
 return `<section class="tree-shop">${node(s.name,'shop:'+s.id,'shop',s.id,'shop')}${contents}</section>`;}).join('');
}
function render(){indexView();
 $('#app').innerHTML=`<header class="topbar"><div class="brand"><span class="brand-symbol">${icon('grid')}</span><strong>配置工作台</strong><span class="version-label">轻量网页版</span></div><nav aria-label="主要导航">${button(icon('grid')+'配置总览','nav-overview',ui.view==='overview'||ui.view==='editor'?'nav-active':'')}${button(icon('calc')+'核算价格','nav-costs',ui.view==='costs'?'nav-active':'')}${button(icon('clock')+'操作记录','nav-logs',ui.view==='logs'?'nav-active':'')}</nav><div class="top-actions">${button(icon('sync')+'ERP 同步','erp','subtle')}${button(icon('cloud')+'云端同步','cloud','primary')}${cloud?`<span class="member-badge" title="${esc('当前用户：'+(cloud.member.name||cloud.member.memberId||'未命名成员'))}" aria-label="${esc('当前用户：'+(cloud.member.name||cloud.member.memberId||'未命名成员'))}">成员：${esc(cloud.member.name||cloud.member.memberId||'未命名成员')}</span>`:'<span class="avatar" title="本地原型，无需登录">演</span>'}</div></header>
 <div class="demo-strip"><span><i></i>${cloud?esc(cloud.label()):'交互原型 · 示例数据'}</span><span class="demo-copy">${cloud?'保存后点击云端同步；ERP 库存保存在本浏览器':'编辑保存在此浏览器，云端与 ERP 尚未连接'}</span>${button(cloud?'导出网页备份':'导出原型数据','export','text-button')}</div>
 <div id="storage-error" role="alert" ${storageError?'':'hidden'}>${esc(storageError)}</div><div class="workspace"><aside class="sidebar ${ui.mobileTree?'mobile-open':''}" aria-label="商品目录"><div class="side-heading"><h2>商品目录</h2>${button(icon('plus')+'新增链接','new-product','text-button')}</div><label class="search tree-search">${icon('search')}<input id="tree-search" aria-label="搜索商品目录" placeholder="搜索商品、配置或模板" value="${esc(ui.treeQuery)}"></label><div id="tree">${tree()}</div><div class="side-footer"><span class="status-dot"></span> 本地草稿自动保留<span>${cloud?'v0.3 云端版':'v0.3 原型'}</span></div></aside><main id="main">${button(icon('menu')+'商品目录','mobile-tree','mobile-menu')}${ui.view==='overview'?overview():ui.view==='editor'?editor():ui.view==='templates'?templatesPage():ui.view==='costs'?costsPage():logsPage()}</main></div>`;
 if(ui.view==='editor')updatePricing();if(ui.view==='overview')renderOverviewRows();
}
function overview(){const all=visibleConfigs(),negative=all.filter(c=>{const t=stats(state.drafts[c.id]||c);return t.erpProfit!==null&&t.erpProfit<0||t.taxProfit!==null&&t.taxProfit<0;}).length,missing=all.filter(c=>{const t=stats(state.drafts[c.id]||c);return t.erp===null||t.tax===null;}).length;
 return `<div class="page-heading"><div><div class="breadcrumb">${crumbs()}</div><h1>${esc(scopeTitle()||'配置总览')}</h1><p>价格、成本与利润，放在一起看清楚。</p></div><div class="heading-actions">${button('批量修改 / 添加配件','batch-open')}${button('勾选模板添加','template-add','')}${button(icon('plus')+'新增配置','new-config','primary')}</div></div><section class="panel overview-panel"><div class="panel-toolbar"><div class="toolbar-left"><label class="search">${icon('search')}<input id="overview-query" placeholder="搜索配置、配件或 SKU" aria-label="搜索配置" value="${esc(ui.query)}"></label><select id="profit-filter" aria-label="利润状态"><option value="all">全部利润状态</option><option value="negative">负利润</option><option value="missing">成本不完整</option><option value="complete">成本完整</option></select><select id="sort" aria-label="排序"><option value="default">默认排序</option><option value="price">到手价从低到高</option><option value="erpProfit">ERP 利润从低到高</option><option value="taxProfit">核算利润从低到高</option></select></div><div class="count-chips"><strong>${all.length} <small>套配置</small></strong>${negative?`<span class="chip red">${negative} 套负利润</span>`:''}${missing?`<span class="chip amber">${missing} 套成本不完整</span>`:''}</div></div><div class="table-scroll"><table class="overview-table"><thead><tr><th>配置 / 主要配件</th><th>到手价</th><th>定价</th><th>ERP 总成本</th><th>核算总成本</th><th>ERP 利润</th><th>核算利润</th><th>操作</th></tr></thead><tbody id="overview-rows"></tbody></table></div><div class="table-footer"><span>店铺优惠券 <strong>${money(shop().coupon)}</strong> ${button('修改','coupon','text-button')}</span><span id="result-count"></span><span>利润已扣除各配置的分期费用</span></div></section><section class="overview-bottom"><div class="panel guide"><span class="guide-icon">${icon('folder')}</span><div><h3>从模板开始，更快配好一套</h3><p>按店铺保存常用方案，勾选需要的配置，添加到当前商品链接。</p></div>${button('选择模板 →','template-add','text-button')}</div><div class="formula"><strong>计算口径</strong><p>定价 = 到手价 + 店铺优惠券</p><p>ERP 利润 = 到手价 × 98% − ERP 总成本 − 分期费</p><p>核算利润 = 到手价 −（核算总成本 × 1.04 + 100）− 分期费</p></div></section>`;
}
function profitCell(value){return value===null?'<span class="incomplete">成本不完整</span>':`<strong class="money ${value<0?'negative':'positive'}">${value>0?'+':''}${money(value)}</strong>`;}
function renderOverviewRows(){if(!$('#overview-rows'))return;const key=JSON.stringify([ui.scope,ui.query,ui.profit,ui.sort]);if(key!==overviewKey){overviewPage=0;overviewKey=key;}$('#profit-filter').value=ui.profit;$('#sort').value=ui.sort;const q=ui.query.toLowerCase();let items=visibleConfigs().map(base=>{const c=state.drafts[base.id]||base;return{c,t:stats(c)};}).filter(({c,t})=>[c.name,c.version,c.skuId,...actualParts(c).map(p=>p.name)].join(' ').toLowerCase().includes(q)&&(ui.profit==='all'||ui.profit==='negative'&&(t.erpProfit!==null&&t.erpProfit<0||t.taxProfit!==null&&t.taxProfit<0)||ui.profit==='missing'&&(t.erp===null||t.tax===null)||ui.profit==='complete'&&t.erp!==null&&t.tax!==null));if(ui.sort!=='default')items.sort((a,b)=>(ui.sort==='price'?a.c.price??Infinity:a.t[ui.sort]??Infinity)-(ui.sort==='price'?b.c.price??Infinity:b.t[ui.sort]??Infinity));
 overviewPage=Math.min(overviewPage,Math.max(0,Math.ceil(items.length/50)-1));$('#overview-rows').innerHTML=items.length?items.slice(overviewPage*50,overviewPage*50+50).map(({c,t})=>{return `<tr class="${c.id===ui.active?'selected-row':''}"><td><button class="config-name config-summary" data-action="edit" data-id="${esc(c.id)}">${summaryMarkup(c)}</button>${state.drafts[c.id]?'<span class="chip amber mini">草稿</span>':''}${c.version?`<small class="config-version">${esc(c.version)}</small>`:''}<small class="row-detail">${c.installment?`${esc(c.installment)} 期 · 费用 ${money(t.fee)}`:'不分期'}${ui.scope.type!=='product'?' · '+esc(state.products.find(p=>p.id===c.productId)?.name):''}</small></td><td class="money">${money(c.price)}</td><td class="money">${money(t.listPrice)}</td><td class="money">${t.erp===null?'<span class="incomplete">待补齐</span>':money(t.erp)}</td><td class="money">${t.tax===null?'<span class="incomplete">待补齐</span>':money(t.tax)}</td><td>${profitCell(t.erpProfit)}</td><td>${profitCell(t.taxProfit)}</td><td>${button('编辑 →','edit','text-button',`data-id="${esc(c.id)}"`)}</td></tr>`;}).join(''):'<tr><td colspan="8"><div class="empty">没有符合条件的配置<p>调整筛选条件，或从模板添加配置。</p></div></td></tr>';$('#result-count').innerHTML=`显示 ${items.length?overviewPage*50+1:0}–${Math.min(items.length,(overviewPage+1)*50)} / 共 ${items.length} 套 ${items.length>50?button('上一页','overview-prev','text-button',overviewPage===0?'disabled':'')+button('下一页','overview-next','text-button',(overviewPage+1)*50>=items.length?'disabled':''):''}`;
}
function configTabs(c){const list=configGroups.get(ui.productId)||[],at=Math.max(0,list.findIndex(r=>r.id===c.id)),start=Math.floor(at/60)*60;return (start?button('← 前 60 套','edit','',`data-id="${esc(list[start-1].id)}"`):'')+list.slice(start,start+60).map(r=>button(`${esc(r.name)} · ${esc(r.version)}${state.drafts[r.id]?' •':''}`,'edit',r.id===c.id?'active':'',`data-id="${esc(r.id)}"`)).join('')+(start+60<list.length?button('后 60 套 →','edit','',`data-id="${esc(list[start+60].id)}"`):'');}
function editor(){const c=current();if(!c)return '<div class="empty">选择一套配置开始编辑。</div>';return `<div class="editor-layout"><div class="editor-main"><div class="page-heading"><div><div class="breadcrumb">${crumbs()}</div><h1>编辑配置 <span class="heading-tag">${esc(c.name)}</span></h1></div><div class="heading-actions">${button('批量修改配件','batch-open')}${button('返回总览','back','text-button')}${button(icon('plus')+'新增','new-config')}${button('使用模板','template-replace')}${button('存为模板','save-template')}${button(icon('undo'),'undo','icon-button',`aria-label="撤销本次未保存修改"`)}</div></div><div class="config-tabs">${configTabs(c)}${button('+','new-config','',`aria-label="新增配置"`)}</div><section class="panel identity"><div class="section-label"><span>基本信息</span><small>当前商品链接下的配置</small></div><div class="form-grid"><label>配置名称<input data-field="name" value="${esc(c.name)}" maxlength="80"></label><label>版本<input data-field="version" value="${esc(c.version)}" maxlength="40"></label><label>SKU ID<input data-field="skuId" value="${esc(c.skuId)}" placeholder="填写真实 SKU ID" inputmode="numeric"></label><label class="span-all">配置简称<div class="input-action"><input data-field="shortName" value="${esc(c.shortName)}" placeholder="例如：14600KF + 5060 Ti + 32G + 1T">${button('自动生成','short-name','text-button')}</div></label></div></section><section class="panel parts-panel"><div class="section-heading"><div><h2>实际配件 <span class="small-badge">${actualParts(c).length} 类</span></h2><p>选择型号、调整数量，右侧自动计算价格与利润。</p></div>${button(icon('plus')+'添加配件','add-part')}</div><div class="table-scroll"><table class="parts-table"><thead><tr><th>配件</th><th>型号 / ERP 商品 ID</th><th>数量</th><th>ERP 单价</th><th>核算单价</th><th>可销库存</th><th></th></tr></thead><tbody>${partsRows(c)}</tbody></table></div><div class="table-footer"><span>ERP 库存和成本均按商品 ID 匹配</span><span>${state.erpSnapshot?'ERP 快照 '+time(state.erpSnapshot.capturedAt):state.erpDemoAt?'演示快照 '+time(state.erpDemoAt):(cloud?'尚未读取 ERP 快照':'示例快照 · 未连接 ERP')}</span></div></section></div><aside class="price-panel panel" aria-label="价格与利润"><div class="price-heading"><span>${icon('calc')}价格与利润</span><small>随编辑即时计算</small></div><div class="price-content"><label class="arrival-label">到手价<div class="arrival-input"><span>¥</span><input id="arrival" data-field="price" type="number" min="0" step="0.01" value="${c.price??''}" aria-label="到手价"></div></label><dl><div><dt>店铺优惠券 ${button('修改','coupon','text-button')}</dt><dd>${money(shop().coupon)}</dd></div><div><dt>定价</dt><dd id="price-list"></dd></div></dl><label class="term-field">分期核算<select data-field="installment" aria-label="分期核算"><option value="0" ${c.installment===0?'selected':''}>不分期</option><option value="12" ${c.installment===12?'selected':''}>12 期 · 6%</option><option value="24" ${c.installment===24?'selected':''}>24 期 · 10%</option></select></label><dl><div><dt>分期费</dt><dd id="price-fee"></dd></div></dl><div id="price-results"></div><div id="draft-status" role="status"></div><div class="save-actions">${button(icon('save')+'保存配置','save','primary')}${button('保存并返回总览','save-back')}</div><p class="local-note">草稿保留在此浏览器<br>云端同步单独操作</p></div></aside></div>`;}
function partsRows(c){return hydrate(c,state.catalog).actualParts.map((p,i)=>`<tr><td><span class="slot-label">${esc(p.slot)}</span></td><td><div class="inline-part-field"><input class="part-pick" data-part-search="${i}" value="${esc(p.name)}" placeholder="输入型号或商品 ID 搜索" aria-label="搜索${esc(p.slot)}配件" autocomplete="off" role="combobox" aria-expanded="false" aria-controls="inline-part-options"><button type="button" data-action="pick-part" data-index="${i}" aria-label="更多配件选择">${icon('arrow')}</button></div><small class="part-id">${p.specialComponent?'特殊配件 · 仅显示，不计成本':p.goodsId?(cloud?'商品 ID ':'示例 ID ')+esc(p.goodsId):'尚未绑定商品'}</small>${addonsUI.block(p,i)}</td><td><input class="qty" type="number" min="1" max="999" step="1" data-qty="${i}" value="${esc(p.qty??'')}" aria-label="${esc(p.slot)}数量"></td><td class="money">${p.specialComponent?'不计成本':money(p.erp)}</td><td class="money">${p.specialComponent?'不计成本':money(p.tax)}</td><td class="stock">${p.specialComponent?'不适用':p.stockAvailable===null?'<span class="incomplete">未知</span>':p.stockAvailable}</td><td>${button(icon('x'),'remove-part','icon-button remove',`data-index="${i}" aria-label="移除第${i+1}行${esc(p.slot)}"`)}</td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">还没有配件，点击「添加配件」开始。</div></td></tr>';}
function updatePricing(){if(ui.view!=='editor'||!$('#price-list'))return;for(const node of $$('.tree-config[data-action="edit"]')){if(node.dataset.id===ui.active){const label=node.querySelector('.config-summary');if(label)label.innerHTML=summaryMarkup(current());}}const t=stats(current());$('#price-list').textContent=money(t.listPrice);$('#price-fee').textContent=money(t.fee);$('#price-results').innerHTML=`<dl class="separated"><div><dt>ERP 总成本</dt><dd>${money(t.erp)}</dd></div><div><dt>核算总成本</dt><dd>${money(t.tax)}</dd></div></dl><dl class="separated profits"><div><dt>ERP 利润</dt><dd>${profitCell(t.erpProfit)}</dd></div><div><dt>核算利润</dt><dd>${profitCell(t.taxProfit)}</dd></div></dl><div class="capacity"><span>当前库存可配</span><strong>${t.capacity===null?'待核对':t.capacity+' <small>台</small>'}</strong></div>${t.erp===null||t.tax===null?'<p class="warning">配件未选齐或成本不完整，对应利润暂不计算。</p>':''}${!t.validQty?'<p class="warning">配件数量必须为正整数。</p>':''}${t.listPrice===null?'<p class="warning">请填写有效到手价。</p>':''}`;const dirty=!!state.drafts[ui.active];$('#draft-status').className=storageError?'warning':dirty?'draft-status':'saved-status';$('#draft-status').textContent=storageError?'草稿未保存：'+storageError:dirty?'● 草稿已保留 · 请保存配置':'✓ 配置已保存';}
function templatesPage(){const list=state.templates.filter(t=>t.shopId===ui.shopId);templateListPage=Math.min(templateListPage,Math.max(0,Math.ceil(list.length/50)-1));return `<div class="page-heading"><div><div class="breadcrumb">${esc(shop().name)} / 配置模板</div><h1>配置模板</h1><p>把常用方案放在这里，下次勾选后直接使用。</p></div>${button('返回配置总览','nav-overview')}</div><div class="template-grid">${list.slice(templateListPage*50,templateListPage*50+50).map(t=>`<section class="panel template-card"><div class="template-symbol">${icon('doc')}</div><h2>${esc(t.name)}</h2><p>${t.configs.length} 套配置 · ${esc(shop().short)}</p><ul>${t.configs.slice(0,5).map(c=>`<li><span>${esc(c.name)} · ${esc(c.version)}</span><strong>${money(c.price)}</strong></li>`).join('')}</ul>${t.configs.length>5?`<p class="muted">另有 ${t.configs.length-5} 套，点开查看并勾选</p>`:''}<div class="template-card-actions">${button('查看 / 勾选套用','template-detail','primary',`data-id="${esc(t.id)}"`)}${button('重命名','rename-template','text-button',`data-id="${esc(t.id)}"`)}</div></section>`).join('')||'<div class="panel empty">暂无模板<p>进入配置编辑页，点击「存为模板」。</p></div>'}</div>${list.length>50?`<div class="list-pagination table-footer"><span>共 ${list.length} 个模板 · 第 ${templateListPage+1} 页</span>${button('上一页','template-list-prev','',templateListPage?'':'disabled')}${button('下一页','template-list-next','',(templateListPage+1)*50>=list.length?'disabled':'')}</div>`:''}`;}
function costsPage(){return addonsUI.costsPage();}
function costRows(q=''){return addonsUI.costRows(q);}
function logsPage(){return `<div class="page-heading"><div><div class="breadcrumb">本地原型</div><h1>操作记录</h1><p>记录已保存的配置、模板和示例成本修改。</p></div>${button('导出原型数据','export')}</div><section class="panel log-list">${state.logs.map(l=>`<div class="log-row"><span class="log-dot"></span><div><strong>${esc(l.message)}</strong><small>仅此浏览器 · 示例数据</small></div><time>${time(l.at)}</time></div>`).join('')||'<div class="empty">还没有操作记录<p>保存一套配置，或勾选模板添加后，记录会显示在这里。</p></div>'}</section>`;}

function openModal(title,body,footer='',submit=null){modalSubmit=submit;const d=$('#modal');d.innerHTML=`<form id="dialog-form"><header><div><small>配置工作台</small><h2 id="modal-title">${title}</h2></div>${button(icon('x'),'close','icon-button',`aria-label="关闭对话框"`)}</header><div class="modal-body">${body}</div><footer><span id="modal-status" role="status"></span><div>${button('取消','close')}${footer}</div></footer></form>`;if(!d.open)d.showModal();syncToastLayer();}
function closeModal(){$('#modal').close();modalSubmit=null;}
function targetOptions(selected=ui.productId){return state.products.filter(p=>p.shopId===ui.shopId).map(p=>`<option value="${esc(p.id)}" ${selected===p.id?'selected':''}>${esc(p.category)} / ${esc(p.name)}</option>`).join('');}
function openNewConfig(){openModal('新增配置',`<p class="modal-intro">选择所属链接，创建空白配置，或者勾选已有模板批量添加。</p><div class="form-grid two"><label class="span-all">所属商品链接<select name="productId" required>${targetOptions()}</select></label><label>配置名称<input name="name" value="配置${state.configs.filter(c=>c.productId===ui.productId).length+1}" required maxlength="80"></label><label>版本<input name="version" value="进阶版" maxlength="40"></label></div><div class="new-template-option">${icon('doc')}<div><strong>已经有类似配置？</strong><p>从模板中勾选所需方案，减少重复输入。</p></div>${button('勾选模板','template-add')}</div>`,`<button class="primary" type="submit">创建空白配置</button>`,f=>{const id=uid(),pid=f.elements.productId.value;if(!pid)throw Error('请先新增商品链接');const c={id,productId:pid,name:f.elements.name.value.trim(),version:f.elements.version.value.trim(),skuId:'',shortName:'',price:0,installment:0,parts:[],actualParts:slots.slice(0,8).map(slot=>({lineId:uid(),slot,goodsId:'',name:'',qty:1}))};validateConfig(c);commit('新增空白配置：'+c.name,()=>{state.configs.push(c);state.drafts[id]=copy(c);});closeModal();openEditor(id);});}
function openEditor(id){const c=state.configs.find(c=>c.id===id);if(!c)return;const p=state.products.find(p=>p.id===c.productId);ui.active=id;ui.productId=p.id;ui.shopId=p.shopId;ui.scope={type:'product',id:p.id};ui.view='editor';ui.mobileTree=false;ui.closed.delete('product:'+p.id);render();}
function openNewProduct(){openModal('新增商品链接',`<div class="form-grid two"><label>店铺<select name="shopId">${state.shops.map(s=>`<option value="${s.id}" ${ui.shopId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>分类<input name="category" list="categories" value="日常主推" required maxlength="60"><datalist id="categories"><option>日常主推</option><option>24期分期</option><option>其他分类</option></datalist></label><label class="span-all">商品链接名称<input name="name" placeholder="例如：乔思伯 D31 游戏主机" required maxlength="100"></label><label class="span-all">SPU（选填）<input name="spu" inputmode="numeric" pattern="[0-9]*" placeholder="保持文本格式，避免长数字丢失精度"></label></div>`,`<button class="primary" type="submit">创建链接</button>`,f=>{const name=f.elements.name.value.trim(),category=f.elements.category.value.trim();if(!name||!category)throw Error('请填写商品名称和分类');if(category==='配置模板')throw Error('配置模板是专用分类，请在编辑页使用「存为模板」');const p={id:uid(),name,category,shopId:f.elements.shopId.value,spu:f.elements.spu.value};commit('新增商品链接：'+name,()=>state.products.push(p));ui.shopId=p.shopId;ui.productId=p.id;ui.scope={type:'product',id:p.id};ui.view='overview';ui.closed.delete('shop:'+p.shopId);closeModal();render();toast('链接已创建，可以新增配置或勾选模板');});}

let templateContext=null,templateListPage=0;
function openTemplatePicker(mode='add',focusId=null){
 const groups=state.templates.filter(t=>t.shopId===ui.shopId).sort((a,b)=>Number(b.id===focusId)-Number(a.id===focusId));templateContext={mode,groups,selected:new Set(),focusId,page:0,query:'',entries:groups.flatMap(t=>t.configs.map((c,i)=>({t,c,key:t.id+':'+i,search:[t.name,c.name,c.version,...actualParts(c).map(p=>p.name)].join(' ').toLowerCase()})))};

 openModal(mode==='replace'?'勾选模板 · 替换当前配置':'勾选模板 · 添加配置',`<p class="modal-intro">${mode==='replace'?'选择一套方案，下一步预览实际配件差异。保留当前名称、SKU、到手价与分期设置。':'勾选需要的配置，可逐套选择或整组全选。新增副本不会改变原模板，SKU 留空待填。'}</p>${mode==='add'?`<label class="target-select">添加到商品链接<select id="template-target" name="productId">${targetOptions()}</select></label><div class="select-all-line"><label><input type="checkbox" id="template-all"> 全选本店模板配置</label><span>${esc(shop().name)}</span></div>`:''}<label class="search modal-search">${icon('search')}<input id="template-search" aria-label="搜索模板配置" placeholder="搜索全部模板、配置或配件"></label><div class="template-picker-list" id="template-picker-rows"></div><div id="template-pagination" class="table-footer list-pagination"></div>`,`<button id="apply-templates" type="submit" class="primary" disabled>${mode==='replace'?'预览替换差异':'添加所选配置'}</button>`,f=>{
 const picks=templateContext.entries.filter(e=>templateContext.selected.has(e.key)).map(e=>e.c);if(!picks.length)throw Error('请先勾选配置');if(mode==='replace'){previewReplacement(picks[0]);return;}
 const pid=f.elements.productId.value;if(!pid)throw Error('请先创建商品链接');const existing=state.configs.filter(c=>c.productId===pid&&!c.deletedAt),count=existing.length,nextOrder=Math.max(-1,...state.configs.map(c=>Number.isFinite(c.workspaceOrder)?c.workspaceOrder:-1))+1;const added=picks.map((c,i)=>({...instantiateTemplate(c,pid,'配置'+(count+i+1)),workspaceOrder:nextOrder+i}));
 commit(`从模板添加 ${added.length} 套配置`,()=>state.configs.push(...added));closeModal();ui.productId=pid;ui.scope={type:'product',id:pid};ui.active=added[0].id;ui.view='overview';ui.closed.delete('product:'+pid);render();toast(`已添加 ${added.length} 套配置，原模板保持不变`);
 });drawTemplateChoices();let timer;const input=$('#template-search');input.oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>{if(!input.isConnected)return;templateContext.query=input.value.trim().toLowerCase();templateContext.page=0;drawTemplateChoices();},120);};
}
function drawTemplateChoices(){const ctx=templateContext,matches=ctx.entries.filter(e=>e.search.includes(ctx.query)),page=matches.slice(ctx.page*50,ctx.page*50+50),groups=[...new Set(page.map(e=>e.t))];$('#template-picker-rows').innerHTML=groups.map(t=>`<details class="template-choice-group" open><summary><input type="checkbox" class="group-check" data-template-group="${esc(t.id)}" aria-label="全选${esc(t.name)}" ${ctx.mode==='replace'?'hidden':''}><span>${esc(t.name)}</span><small>${t.configs.length} 套</small></summary><div>${page.filter(e=>e.t===t).map(({c,key})=>`<label class="template-choice"><input type="${ctx.mode==='replace'?'radio':'checkbox'}" name="templatePick" data-template-choice="${esc(key)}" value="${esc(key)}"><span><strong>${esc(c.name)} · ${esc(c.version)}</strong><small>${esc(actualParts(c).filter(p=>['CPU','显卡'].includes(p.slot)).map(p=>p.name).join(' / '))}</small></span><b>${money(c.price)}</b></label>`).join('')}</div></details>`).join('')||'<div class="empty">没有匹配的模板配置</div>';$('#template-pagination').innerHTML=`<span>共 ${matches.length} 套 · 第 ${ctx.page+1} / ${Math.max(1,Math.ceil(matches.length/50))} 页</span><div>${button('上一页','template-page-prev','',ctx.page?'':'disabled')}${button('下一页','template-page-next','',(ctx.page+1)*50>=matches.length?'disabled':'')}</div>`;updateTemplateSelection();}
function updateTemplateSelection(){const ctx=templateContext;if(!ctx)return;for(const el of $$('[data-template-choice]'))el.checked=ctx.selected.has(el.value);for(const el of $$('[data-template-group]')){const entries=ctx.entries.filter(e=>e.t.id===el.dataset.templateGroup),n=entries.filter(e=>ctx.selected.has(e.key)).length;el.checked=n>0&&n===entries.length;el.indeterminate=n>0&&!el.checked;}const all=$('#template-all');if(all){all.checked=ctx.selected.size>0&&ctx.selected.size===ctx.entries.length;all.indeterminate=ctx.selected.size>0&&!all.checked;}$('#modal-status').textContent=`已选 ${ctx.selected.size} 套`;$('#apply-templates').disabled=!ctx.selected.size;}

function previewReplacement(source){const target=current(),rows=templateDiff(target,source);openModal('预览模板替换差异',`<p class="modal-intro">只替换实际配件。当前配置名称、商品链接、SKU、售价、分期和展示信息保留。</p><div class="table-scroll"><table class="diff-table"><thead><tr><th>配件</th><th>当前配置</th><th>模板方案</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.slot)}</td><td>${esc(r.before)}</td><td>${esc(r.after)}</td></tr>`).join('')||'<tr><td colspan="3">实际配件一致，无需替换。</td></tr>'}</tbody></table></div>`,`<button class="primary" type="submit" ${rows.length?'':'disabled'}>应用到当前配置</button>`,()=>{edit(c=>Object.assign(c,replaceFromTemplate(c,source)));closeModal();render();toast('模板已应用到草稿，保存前可撤销');});}
function openSaveTemplate(){const c=current();if(!c)throw Error('请先选择一套配置');validateConfig(c);openModal('存为模板',`<p class="modal-intro">保存在「${esc(shop().name)} → 配置模板」，以后可勾选其中的配置重复使用。</p><label class="block-label">模板名称<input name="name" value="${esc(product()?.name+' 常用方案')}" required maxlength="80"></label><fieldset class="radio-options"><legend>保存范围</legend><label><input type="radio" name="scope" value="current" checked> 当前这套配置 <small>使用当前编辑内容</small></label><label><input type="radio" name="scope" value="product"> 当前链接的全部配置 <small>包含此链接已保留的草稿</small></label></fieldset>`,`<button class="primary" type="submit">保存模板</button>`,f=>{const name=f.elements.name.value.trim();if(!name)throw Error('请填写模板名称');const configs=f.elements.scope.value==='current'?[current()]:state.configs.filter(x=>x.productId===ui.productId).map(x=>state.drafts[x.id]||x);configs.forEach(validateConfig);commit('保存模板：'+name,()=>state.templates.push({id:uid(),shopId:ui.shopId,name,configs:configs.map(c=>snapshotOptions(state,c,ui.shopId))}));ui.closed.delete('templates:'+ui.shopId);closeModal();render();toast(`已保存 ${configs.length} 套配置为模板`);});}
function partEntries(index){
 const row=actualParts(current())[index],byGoods=new Map();
 if(cloud)for(const source of state.sources){if(source.shopId!==ui.shopId)continue;const list=byGoods.get(source.goodsId)||[];list.push(source);byGoods.set(source.goodsId,list);}
 const entries=state.catalog.filter(p=>row.slot.startsWith('配件')||p.slot===row.slot||cloud&&p.slot==='配件').flatMap(p=>{const sources=byGoods.get(p.goodsId);return sources?.length?sources.map(s=>({...p,name:s.name,sourceId:s.sourceId,search:(p.name+' '+s.name+' '+p.goodsId).toLowerCase()})):[{...p,search:(p.name+' '+p.goodsId).toLowerCase()}];});
 return entries;
}
let pickerSpecials=[];
function openPartPicker(index){
 pickerSpecials=specialChoices(state,ui.shopId);
 const row=actualParts(current())[index],entries=partEntries(index);
 openModal('选择'+row.slot,`<label class="search modal-search">${icon('search')}<input id="part-query" placeholder="搜索型号或商品 ID" aria-label="搜索配件"></label><p class="muted">选择后按商品 ID 绑定成本和库存。搜索覆盖全部商品，每页显示 60 项。</p><label class="special-only"><input id="part-special-only" type="checkbox"> 只看特殊配件（仅显示，不计成本）</label><div class="special-custom"><label for="special-name">自定义特殊配件</label><div class="input-action"><input id="special-name" maxlength="160" placeholder="填写显示内容，例如：客户自备显卡">${button('使用此说明','choose-special-custom','',`data-index="${index}"`)}</div></div><div id="part-options" class="part-options"></div><div id="part-pagination" class="list-pagination table-footer"></div>`);
 entries.push(...pickerSpecials.map((p,i)=>({...p,specialIndex:i,search:p.name.toLowerCase()})));
 let page=0,query='',timer;const input=$('#part-query');
 const draw=()=>{const matches=entries.filter(p=>(!$('#part-special-only').checked||p.specialComponent)&&p.search.includes(query)),start=page*60;$('#part-options').innerHTML=matches.slice(start,start+60).map(p=>`<button class="part-option" data-action="${p.specialComponent?'choose-special':'choose-part'}" data-special="${p.specialIndex??''}" data-index="${index}" data-id="${esc(p.goodsId)}" data-source="${esc(p.sourceId||'')}"><span><strong>${esc(p.name)}</strong><small>${p.specialComponent?'特殊配件 · 仅显示':(cloud?'商品':'示例')+' ID '+esc(p.goodsId)}</small></span><span>${p.specialComponent?'<small>不计成本 · 不占库存</small>':`<small>ERP ${money(p.erp)} · 核算 ${money(p.tax)}</small><b>库存 ${p.stockAvailable??'未知'}</b>`}</span></button>`).join('')||'<p class="empty">没有找到匹配配件，请尝试其他关键词。</p>';$('#part-pagination').innerHTML=`<span>显示 ${matches.length?start+1:0}–${Math.min(start+60,matches.length)} / 共 ${matches.length} 项</span><div><button type="button" id="part-prev" ${page?'':'disabled'}>上一页</button><button type="button" id="part-next" ${start+60>=matches.length?'disabled':''}>下一页</button></div>`;$('#part-prev').onclick=()=>{page--;draw();};$('#part-next').onclick=()=>{page++;draw();};};
 $('#part-special-only').onchange=()=>{clearTimeout(timer);query='';input.value='';page=0;draw();};draw();input.oninput=()=>{clearTimeout(timer);const search=()=>{if(!input.isConnected)return;query=input.value.trim().toLowerCase();page=0;draw();};if(entries.length<200)search();else timer=setTimeout(search,120);};
}
function openCoupon(){openModal('修改店铺优惠券',`<p class="modal-intro">${esc(shop().name)}共用此金额。修改后，本店全部配置的定价一起更新。</p><label class="block-label">优惠券金额（元）<input name="coupon" type="number" min="0" step="0.01" required value="${shop().coupon}"></label>`,`<button class="primary" type="submit">保存优惠券</button>`,f=>{const value=Number(f.elements.coupon.value);if(!Number.isFinite(value)||value<0)throw Error('优惠券金额无效');commit('修改'+shop().short+'优惠券',()=>shop().coupon=value);closeModal();render();});}
function editCost(id){const p=state.catalog.find(p=>p.goodsId===id);openModal('编辑核算单价',`<p class="modal-intro">${esc(p.name)} · ${cloud?'商品':'示例'} ID ${esc(p.goodsId)}</p><div class="cost-before"><span>当前核算价</span><strong>${money(p.tax)}</strong></div><label class="block-label">新核算单价（元）<input name="tax" type="number" min="0" step="0.01" value="${p.tax??''}" placeholder="留空表示成本待补齐"></label><p class="warning">保存后，所有使用该商品的配置按新核算价计算利润。ERP 成本保持不变。</p>`,`<button class="primary" type="submit">确认并保存核算价</button>`,f=>{const value=f.elements.tax.value===''?null:Number(f.elements.tax.value);if(value!==null&&(!Number.isFinite(value)||value<0))throw Error('核算价无效');commit('修改核算价：'+p.name,()=>p.tax=value);closeModal();render();toast('核算价已保存，关联利润已更新');});}
function openErp(){if(cloud)return webErp.open();const p=state.catalog.find(p=>p.goodsId==='990006');const changed=!!state.erpDemoAt;openModal('ERP 库存与成本 · 演示',`<div class="notice-box">本原型尚未连接 ERP。以下是用于体验流程的固定示例快照，不代表实际库存或价格。</div><p class="modal-intro">公司大库 · 只读商品 ID、ERP 成本与可销库存</p><div class="table-scroll"><table class="diff-table"><thead><tr><th>示例商品</th><th>ERP 成本</th><th>可销库存</th></tr></thead><tbody><tr><td>${esc(p.name)}<small class="part-id">${esc(p.goodsId)}</small></td><td>${money(p.erp)} → ¥2,500.00</td><td>${p.stockAvailable} → 9</td></tr></tbody></table></div><p class="muted">确认后仅更新此原型中的示例成本和库存，人工核算价保留。${changed?'此快照之前已应用。':''}</p>`,`<button class="primary" type="submit" ${changed?'disabled':''}>应用示例快照</button>`,()=>{commit('应用 ERP 示例快照（非真实同步）',()=>{p.erp=2500;p.stockAvailable=9;state.erpDemoAt=new Date().toISOString();});closeModal();render();toast('示例快照已应用，关联配置已重新计算');});}
function openCloud(){if(cloud)return cloud.open();openModal('云端同步 · 接入说明',`<div class="notice-box">此交互原型尚未连接云端，也不会读取或上传现有工作台数据。</div><div class="connection-flow"><span>浏览器草稿</span>${icon('arrow')}<span>手动同步</span>${icon('arrow')}<span>现有云端工作区</span></div><p>正式接入后，将沿用现有成员账号、云端配置与模板，支持拉取更新和提交编辑。ERP 库存与成本保持独立读取。</p><p class="muted">现在可以先体验编辑、保存、模板和利润计算，原型内容保存在当前浏览器。</p>`,button('进入云端工作区','cloud-enter','primary')+button('导出原型数据','export'));}

$('#app').addEventListener('click',handleClick);$('#modal').addEventListener('click',handleClick);
function handleClick(e){const b=e.target.closest('[data-action]');if(!b)return;const {action,id,index}=b.dataset;run(()=>{
 if(action.startsWith('web-erp-'))return webErp.actions(action);
 if(action.startsWith('batch-'))return batchUI.actions(action);
 if(action==='close'){if(cloud?.busy)return;return closeModal();}if(action==='cloud-enter'){location.href='./cloud.html';return;}if(cloud?.actions(action,b.dataset))return;if(action==='export'){download(corruptRaw&&rawStorage?rawStorage:state,'配置工作台-网页备份.json');return;}
 if(action==='template-list-prev'||action==='template-list-next'){templateListPage+=action==='template-list-next'?1:-1;render();return;}
 if(action==='template-page-prev'||action==='template-page-next'){templateContext.page+=action==='template-page-next'?1:-1;drawTemplateChoices();return;}
 if(action==='overview-prev'||action==='overview-next'){overviewPage+=action==='overview-next'?1:-1;renderOverviewRows();return;}
 if(action==='tree-prev'||action==='tree-next'){treePages.set(id,Math.max(0,(treePages.get(id)||0)+(action==='tree-next'?1:-1)));$('#tree').innerHTML=tree();return;}
 if(action==='toggle'){ui.closed.has(id)?ui.closed.delete(id):ui.closed.add(id);$('#tree').innerHTML=tree();return;}
 if(action==='mobile-tree'){ui.mobileTree=!ui.mobileTree;$('.sidebar').classList.toggle('mobile-open',ui.mobileTree);return;}
 if(action==='edit')return openEditor(id);
 if(action==='product'){const p=state.products.find(p=>p.id===id);Object.assign(ui,{view:'overview',shopId:p.shopId,productId:id,scope:{type:'product',id},query:'',profit:'all',mobileTree:false});ui.closed.delete('product:'+id);render();return;}
 if(action==='shop'||action==='category'){const [sid,category]=id.split('|');ui.shopId=sid;ui.scope={type:action,id:sid,category};ui.productId=state.products.find(p=>p.shopId===sid&&(!category||p.category===category))?.id;ui.view='overview';ui.query='';ui.profit='all';render();return;}
 if(action.startsWith('nav-')){const previous=ui.view;ui.view=action.slice(4);if(ui.view==='overview'){if(!product()||product().shopId!==ui.shopId)ui.productId=state.products.find(p=>p.shopId===ui.shopId)?.id;if(previous==='templates')ui.scope=ui.productId?{type:'product',id:ui.productId}:{type:'shop',id:ui.shopId};}render();return;}
 if(action==='back'){ui.view='overview';render();return;}
 if(action==='templates'){ui.shopId=id;ui.view='templates';ui.productId=state.products.find(p=>p.shopId===id)?.id;render();return;}
 if(action==='template-detail'){const t=state.templates.find(t=>t.id===id);ui.shopId=t.shopId;if(!product()||product().shopId!==t.shopId)ui.productId=state.products.find(p=>p.shopId===t.shopId)?.id;openTemplatePicker('add',id);return;}
 if(action==='cloud')return openCloud();if(action==='erp')return openErp();
 if(locked)throw Error(storageError);if(cloud?.busy)throw Error('同步进行中，请稍后编辑');
 if(addonsUI.actions(action,b.dataset))return;
 if(action==='new-product')return openNewProduct();if(action==='new-config')return openNewConfig();
 if(action==='template-add')return openTemplatePicker('add');if(action==='template-replace')return openTemplatePicker('replace');if(action==='save-template')return openSaveTemplate();
 if(action==='save'||action==='save-back')return saveCurrent(action==='save-back');
 if(action==='undo'){if(!state.drafts[ui.active])return toast('当前没有未保存修改');openModal('撤销未保存修改',`<p>恢复到这套配置上次保存的内容？其他配置和模板保持不变。</p>`,`<button class="primary" type="submit">撤销修改</button>`,()=>{commit('撤销配置草稿',()=>delete state.drafts[ui.active]);closeModal();render();});return;}
 if(action==='short-name'){const c=current();const text=actualParts(c).filter(p=>['CPU','显卡','内存','硬盘'].includes(p.slot)).map(p=>p.name+(p.qty>1?' × '+p.qty:'')).join(' + ');edit(c=>c.shortName=text);render();return;}
 if(action==='pick-part')return openPartPicker(Number(index));
 if(action==='choose-special'||action==='choose-special-custom'){const source=action==='choose-special-custom'?{name:$('#special-name').value}:pickerSpecials[Number(b.dataset.special)];if(!source)throw Error('特殊配件已变化，请重新选择');edit(c=>applySpecialPart(c.actualParts[Number(index)],source));closeModal();render();return;}
 if(action==='choose-part'){const p=state.catalog.find(p=>p.goodsId===id);edit(c=>{const part=c.actualParts[Number(index)];if(part.goodsId!==p.goodsId||b.dataset.source&&part.sourceId!==b.dataset.source)delete part.addonOverride;const source=sourceFor(state,ui.shopId,p.goodsId,b.dataset.source);Object.assign(part,{specialComponent:false,goodsId:p.goodsId,name:source.name,...(cloud?{sourceId:source.sourceId}:{})});});closeModal();render();return;}
 if(action==='remove-part'){edit(c=>c.actualParts.splice(Number(index),1));render();return;}
 if(action==='add-part'){const free=slots.filter(slot=>!actualParts(current()).some(p=>p.slot===slot));if(!free.length)return toast('14 个 ERP 槽位已用完，请修改已有配件');openModal('添加配件',`<label class="block-label">添加到空槽位<select name="slot">${free.map(s=>`<option>${s}</option>`).join('')}</select></label><label class="block-label">数量<input name="qty" type="number" min="1" max="100000" step="1" value="1" required></label><p class="muted">添加后选择普通或特殊配件。当前已有的配件槽位不会重复添加。</p>`,`<button class="primary" type="submit">添加并选择配件</button>`,f=>{const slot=f.elements.slot.value,qty=Number(f.elements.qty.value);if(!free.includes(slot)||actualParts(current()).some(p=>p.slot===slot))throw Error('此槽位已占用');if(!Number.isInteger(qty)||qty<1||qty>100000)throw Error('数量必须为有效正整数');edit(c=>c.actualParts.push({lineId:uid(),slot,name:'',goodsId:'',qty}));closeModal();render();openPartPicker(actualParts(current()).length-1);});return;}
 if(action==='coupon')return openCoupon();if(action==='edit-cost')return editCost(id);
 if(action==='rename-template'){const t=state.templates.find(t=>t.id===id);openModal('重命名模板',`<label class="block-label">模板名称<input name="name" value="${esc(t.name)}" required maxlength="80"></label>`,`<button class="primary" type="submit">保存名称</button>`,f=>{const name=f.elements.name.value.trim();if(!name)throw Error('模板名称不能为空');commit('重命名模板',()=>t.name=name);closeModal();render();});}
 });}
$('#app').addEventListener('input',e=>run(()=>{const el=e.target;if(el.id==='tree-search'){ui.treeQuery=el.value;treePages.clear();clearTimeout(el.searchTimer);if(state.configs.length<200)$('#tree').innerHTML=tree();else el.searchTimer=setTimeout(()=>{if(el.isConnected)$('#tree').innerHTML=tree();},120);return;}if(el.id==='overview-query'){ui.query=el.value;clearTimeout(el.searchTimer);if(state.configs.length<200)renderOverviewRows();else el.searchTimer=setTimeout(()=>{if(el.isConnected)renderOverviewRows();},120);return;}if(el.id==='cost-query'){addonsUI.searchCosts(el.value);return;}if(el.dataset.field){const key=el.dataset.field;edit(c=>c[key]=key==='price'?(el.value===''?null:Number(el.value)):key==='installment'?Number(el.value):el.value);return;}if(el.dataset.qty!==undefined)edit(c=>c.actualParts[Number(el.dataset.qty)].qty=el.value===''?null:Number(el.value));}));
$('#app').addEventListener('change',e=>{if(e.target.id==='profit-filter'){ui.profit=e.target.value;renderOverviewRows();}if(e.target.id==='sort'){ui.sort=e.target.value;renderOverviewRows();}});
$('#modal').addEventListener('change',e=>{const el=e.target,ctx=templateContext;if(!ctx)return;if(el.id==='template-all'||el.dataset.templateGroup){for(const entry of ctx.entries){if(el.dataset.templateGroup&&entry.t.id!==el.dataset.templateGroup)continue;if(el.checked)ctx.selected.add(entry.key);else ctx.selected.delete(entry.key);}updateTemplateSelection();}else if(el.dataset.templateChoice){if(ctx.mode==='replace')ctx.selected.clear();if(el.checked)ctx.selected.add(el.value);else ctx.selected.delete(el.value);updateTemplateSelection();}});
$('#modal').addEventListener('click',e=>{if(e.target.matches('.group-check'))e.stopPropagation();});
$('#modal').addEventListener('submit',async e=>{e.preventDefault();if(!e.target.reportValidity())return;try{await modalSubmit?.(e.target);if(cloud)await cloud.flush();}catch(error){$('#modal-status').textContent=error.message;}});
window.addEventListener('storage',e=>{if(e.key===storageKey&&e.newValue!==JSON.stringify(state)){locked=true;storageError='另一窗口已修改原型数据。请先导出当前副本，再刷新继续。';$('#storage-error').hidden=false;$('#storage-error').textContent=storageError;}});
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();if(ui.view==='editor'&&!$('#modal').open)run(()=>saveCurrent());}});
const webErp=createWebErp({request:(action,data)=>cloud.inventory(action,data),state:()=>state,esc,openModal,button,download,commit,closeModal,render,toast,busy:()=>!!cloud?.busy||locked,flush:()=>cloud?.flush()});
const batchUI=createBatchUI({state:()=>state,shopId:()=>ui.shopId,productId:()=>ui.productId,esc,button,openModal,closeModal,toast,render,async apply(plan){
 if(cloud?.busy||locked)throw Error('工作区正在同步或已锁定，请稍后重试');
 const currentById=new Map(state.configs.map(c=>[c.id,c])),productsById=new Map(state.products.map(p=>[p.id,p]));
 for(const change of plan){const base=currentById.get(change.id),p=productsById.get(base?.productId),now=base?{...copy(state.drafts[base.id]||base),shopId:p?.shopId,product:p?.name}:null;if(JSON.stringify(now)!==JSON.stringify(change.before))throw Error('配置已变化，请重新打开批量修改并预览');validateConfig(change.after);}
 const changes=new Map(plan.map(c=>[c.id,c.after]));commit(`批量修改配件：${plan.length} 套配置`,()=>{state.configs=state.configs.map(c=>changes.has(c.id)?copy(changes.get(c.id)):c);for(const id of changes.keys())delete state.drafts[id];});if(cloud)await cloud.flush();
}});
const addonsUI=createAddonUI({state:()=>state,shopId:()=>ui.shopId,current,selectShop:id=>{ui.shopId=id;ui.productId=state.products.find(p=>p.shopId===id)?.id;ui.scope={type:'shop',id};},esc,money,icon,button,openModal,closeModal,render,commit,edit,toast});
if((!rawStorage||sourceMigration)&&!locked)try{persist();}catch(e){storageError='浏览器存储不可用：'+e.message;}
if(cloud)for(const p of state.products)ui.closed.add('product:'+p.id);
if(!cloud)render();

if(cloud){
 const replace=next=>{if(next!==state)state=copy(next);knownRevision=state.revision||0;if(!state.products.some(p=>p.id===ui.productId)){const p=state.products[0];ui.productId=p?.id;ui.shopId=p?.shopId||state.shops[0].id;ui.scope=p?{type:'product',id:p.id}:{type:'shop',id:ui.shopId};}if(!state.configs.some(c=>c.id===ui.active))ui.active=state.configs[0]?.id;render();};
 cloud.attach({getState:()=>state,openModal,toast,replace,
  storageFailed(error){locked=true;storageError=error.message;const warning=$('#storage-error');if(warning){warning.hidden=false;warning.textContent=storageError;}toast(storageError);},
  async persistCloud(next){if(locked)throw Error(storageError);await cloud.write(next);state=copy(next);knownRevision=next.revision;},
 });
 replace(state);
}

// Inline search keeps queries transient; only a selected result changes the draft.
let inlinePart=null,inlineTimer;
function closeInlinePart(){clearTimeout(inlineTimer);if(inlinePart){const {input,original}=inlinePart;if(input.isConnected){input.value=original;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}inlinePart.panel.remove();inlinePart=null;}}
document.addEventListener('focusin',e=>{const input=e.target.closest('[data-part-search]');if(!input)return;closeInlinePart();const index=Number(input.dataset.partSearch),panel=document.createElement('div');panel.id='inline-part-options';panel.className='inline-part-options';panel.setAttribute('role','listbox');panel.addEventListener('click',handleClick);document.body.append(panel);pickerSpecials=specialChoices(state,ui.shopId);const entries=partEntries(index).concat(pickerSpecials.map((p,i)=>({...p,specialIndex:i,search:p.name.toLowerCase()})));inlinePart={input,panel,original:input.value,entries,index,active:-1};input.setAttribute('aria-expanded','true');input.select();drawInlinePart('');});
function drawInlinePart(query){if(!inlinePart)return;const {input,panel,entries,index}=inlinePart;if(!input.isConnected){closeInlinePart();return;}const q=query.trim().toLowerCase(),matches=entries.filter(p=>p.search.includes(q)),r=input.getBoundingClientRect(),width=Math.min(Math.max(r.width,340),innerWidth-16),below=innerHeight-r.bottom-12;panel.style.cssText=`left:${Math.max(8,Math.min(r.left,innerWidth-width-8))}px;width:${width}px;max-height:${Math.min(320,Math.max(below, r.top-12))}px;${below>=180?'top:'+ (r.bottom+4)+'px':'bottom:'+(innerHeight-r.top+4)+'px'}`;const mark=name=>{const at=name.toLowerCase().indexOf(q);return q&&at>=0?esc(name.slice(0,at))+'<mark>'+esc(name.slice(at,at+q.length))+'</mark>'+esc(name.slice(at+q.length)):esc(name);};panel.innerHTML=matches.slice(0,60).map((p,i)=>`<button type="button" role="option" aria-selected="false" id="inline-option-${i}" data-action="${p.specialComponent?'choose-special':'choose-part'}" data-index="${index}" data-id="${esc(p.goodsId)}" data-source="${esc(p.sourceId||'')}" data-special="${p.specialIndex??''}"><strong>${mark(p.name)}</strong><small>${p.specialComponent?'特殊配件 · 仅显示，不计成本':'ID '+esc(p.goodsId)+' · 库存 '+esc(p.stockAvailable??'未知')+' · ERP '+money(p.erp)+' · 核算 '+money(p.tax)}</small></button>`).join('')+`<div class="inline-part-note">${matches.length?matches.length>60?'显示前 60 项，请继续输入关键词缩小范围':'共 '+matches.length+' 项':'没有匹配配件，可点击右侧箭头添加特殊说明'}</div>`;inlinePart.active=-1;input.removeAttribute('aria-activedescendant');}
document.addEventListener('input',e=>{if(e.target!==inlinePart?.input)return;clearTimeout(inlineTimer);inlineTimer=setTimeout(()=>drawInlinePart(e.target.value),100);});
document.addEventListener('keydown',e=>{if(e.target!==inlinePart?.input)return;if(e.key==='Escape'){e.preventDefault();closeInlinePart();return;}if(!['ArrowDown','ArrowUp','Enter'].includes(e.key))return;e.preventDefault();const options=[...inlinePart.panel.querySelectorAll('[role=option]')];if(e.key==='Enter'){if(inlinePart.active>=0)options[inlinePart.active]?.click();return;}inlinePart.active=Math.max(0,Math.min(options.length-1,inlinePart.active+(e.key==='ArrowDown'?1:-1)));options.forEach((el,i)=>el.setAttribute('aria-selected',String(i===inlinePart.active)));const selected=options[inlinePart.active];if(selected){e.target.setAttribute('aria-activedescendant',selected.id);selected.scrollIntoView({block:'nearest'});}});
document.addEventListener('pointerdown',e=>{if(inlinePart&&!inlinePart.panel.contains(e.target)&&e.target!==inlinePart.input)closeInlinePart();});
document.addEventListener('focusout',e=>{if(e.target===inlinePart?.input)setTimeout(()=>{if(inlinePart&&!inlinePart.panel.contains(document.activeElement)&&document.activeElement!==inlinePart.input)closeInlinePart();},0);});
document.addEventListener('click',e=>{if(inlinePart?.panel.contains(e.target)&&e.target.closest('[role=option]'))closeInlinePart();});
window.addEventListener('resize',closeInlinePart);document.addEventListener('scroll',e=>{if(inlinePart&&!inlinePart.panel.contains(e.target))closeInlinePart();},true);
